// Split each manual into section-sized chunks (a section = text under a "## " heading).
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary?.data;
  if (!bin) continue;
  const name = bin.fileName || 'unknown';
  if (!/\.(md|txt)$/i.test(name)) { continue; } // PDF is only supported by the vector pipeline
  const text = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8');
  const sections = text.split(/\n(?=## )/).map((s) => s.trim()).filter((s) => s.length > 80);
  sections.forEach((s, k) => out.push({ json: { source: name, chunkId: `${name}#${k}`, text: s } }));
}
return out;

const chunk = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.attempts = 0;
const prompt = `You extract a knowledge graph from a technical manual fragment (the manual is in Spanish).
Return ONLY JSON: {"entities":[{"name","type","description"}],"relations":[{"source","target","type","evidence"}]}.
Rules:
- Entity types: Device, System, Component, Message, Segment, Field, Parameter, Port, Protocol, ErrorCode, Procedure, Symptom, Event, Config.
- Use short canonical names exactly as written in the text; reuse the same name for the same thing (e.g. always "ACME M-100", "HIS", "ACK", "MLLP", "puerto 6661" -> entity "Puerto 6661").
- description: one concise sentence in Spanish with the concrete facts (values, formats, byte codes, timings, example frames if short).
- Relation types (UPPER_SNAKE_CASE), prefer: SENDS, SENDS_TO, RECEIVES_FROM, CONNECTS_TO, LISTENS_ON, USES, CONTAINS, HAS_FIELD, HAS_PARAMETER, CONFIGURED_BY, RAISES, CAUSED_BY, RESOLVED_BY, DEPENDS_ON, RESPONDS_WITH, REQUIRES, AFFECTS, PART_OF, MANIFESTS_AS.
- evidence: a very short quote or paraphrase (max 15 words) from the fragment.
- Only facts stated in the fragment. No duplicates.

Fragment (${chunk.source}):
${chunk.text}`;
const body = { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0, responseMimeType: 'application/json' } };
return [{ json: { ...chunk, body } }];

const sd = $getWorkflowStaticData('global');
sd.attempts = (sd.attempts || 0) + 1;
const code = $input.first().json.statusCode;
if (sd.attempts > 6) throw new Error(`Gemini kept failing (last HTTP ${code}) after 6 retries. Free-tier quota may be exhausted; wait and re-run.`);
return [{ json: { ...$('Preparar prompt').first().json, attempt: sd.attempts, lastStatus: code } }];

const res = $input.first().json;
const chunk = $('Preparar prompt').first().json;
if (res.statusCode !== 200) throw new Error(`Gemini HTTP ${res.statusCode}: ${JSON.stringify(res.body).slice(0, 300)}`);
let g;
try {
  const txt = res.body.candidates[0].content.parts[0].text;
  g = JSON.parse(txt.replace(/^```json\s*|```\s*$/g, ''));
} catch (e) { throw new Error('Could not parse Gemini JSON: ' + e.message); }
const key = (s) => String(s).toLowerCase().replace(/\s+/g, ' ').trim();
const ents = new Map();
const addEnt = (name, type, description) => {
  if (!name) return;
  const k = key(name);
  const prev = ents.get(k);
  if (!prev || (description || '').length > (prev.description || '').length) ents.set(k, { key: k, name: String(name).trim(), type: type || 'Unknown', description: description || '' });
};
for (const e of g.entities || []) addEnt(e.name, e.type, e.description);
const rels = [];
for (const r of g.relations || []) {
  if (!r.source || !r.target) continue;
  const type = String(r.type || 'RELATED_TO').toUpperCase().replace(/[^A-Z0-9_]/g, '_').replace(/^_+|_+$/g, '').slice(0, 40) || 'RELATED_TO';
  if (!ents.has(key(r.source))) addEnt(r.source, 'Unknown', '');
  if (!ents.has(key(r.target))) addEnt(r.target, 'Unknown', '');
  rels.push({ a: key(r.source), b: key(r.target), type, evidence: String(r.evidence || '').slice(0, 200) });
}
const st = [{ statement: 'MERGE (c:Chunk {id:$id}) SET c.text=$text, c.source=$source', parameters: { id: chunk.chunkId, text: chunk.text, source: chunk.source } }];
for (const e of ents.values()) {
  // keep the longest description seen so far (the same entity appears in several chunks/manuals)
  st.push({ statement: "MERGE (e:Entity {key:$key}) SET e.name=coalesce(e.name,$name), e.type=CASE WHEN e.type IS NULL OR e.type='Unknown' THEN $type ELSE e.type END, e.description=CASE WHEN e.description IS NULL OR size(e.description)<size($description) THEN $description ELSE e.description END", parameters: e });
  st.push({ statement: 'MATCH (c:Chunk {id:$id}),(e:Entity {key:$key}) MERGE (c)-[:MENTIONS]->(e)', parameters: { id: chunk.chunkId, key: e.key } });
}
for (const r of rels) st.push({ statement: `MATCH (a:Entity {key:$a}),(b:Entity {key:$b}) MERGE (a)-[r:${r.type}]->(b) SET r.evidence=$evidence`, parameters: r });
return [{ json: { chunkId: chunk.chunkId, entities: ents.size, relations: rels.length, statements: st } }];

const r = $input.first().json;
const p = $('Parsear a Cypher').first().json;
if (r.errors && r.errors.length) throw new Error('Neo4j: ' + JSON.stringify(r.errors).slice(0, 400));
return [{ json: { chunkId: p.chunkId, entities: p.entities, relations: p.relations, status: 'ok' } }];

const r = $input.first().json;
if (r.errors && r.errors.length) throw new Error('Neo4j: ' + JSON.stringify(r.errors).slice(0, 400));
const rows = (i) => r.results[i].data.map((d) => d.row);
return [{ json: {
  nodesByLabel: Object.fromEntries(rows(0)),
  relationshipsByType: Object.fromEntries(rows(1)),
  sampleCypher: "MATCH (a:Entity)-[r]->(b:Entity) RETURN a.name, type(r), b.name LIMIT 25",
  hint: 'Open http://localhost:7474 (user neo4j) and run the sample Cypher, or: MATCH p=()-[]->() RETURN p LIMIT 100',
} }];
